var n=`1371-tequenos`;var t=`world-1371`;var o=`VE`;var s=`south-america`;var a=8;var r=52;var u={en:`Tequeños`,ua:`Текеньйос`};var l={en:`Tequeños is a dish from Venezuela featuring all-purpose flour, queso blanco, hot sauce. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Текеньйос, страва кухні країни Венесуела з такими основними складниками: пшеничне борошно універсальне, сир кесо бланко, гострий соус. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,470,`g`],[`unsalted-butter`,105,`g`],[`water`,230,`ml`],[`table-salt`,8,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:6,i:[[`queso-blanco`,350,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`canola-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`hot-sauce`,60,`ml`]]}];var g={slug:n,id:t,country:`VE`,region:s,servings:8,minutes:52,title:u,text:l,steps:h};export{o as country,g as default,t as id,r as minutes,s as region,a as servings,n as slug,h as steps,l as text,u as title};